def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = set()
            while stack:
                y, x = stack.pop()
                cells.add((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == color and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            minr = min(y for y, x in cells)
            maxr = max(y for y, x in cells)
            minc = min(x for y, x in cells)
            maxc = max(x for y, x in cells)

            # Identify shapes with enclosed empty cells.
            exterior = set()
            flood = []
            for y in range(minr, maxr + 1):
                for x in range(minc, maxc + 1):
                    if (y in (minr, maxr) or x in (minc, maxc)) and (y, x) not in cells:
                        if (y, x) not in exterior:
                            exterior.add((y, x))
                            flood.append((y, x))
            while flood:
                y, x = flood.pop()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (minr <= ny <= maxr and minc <= nx <= maxc and
                            (ny, nx) not in cells and (ny, nx) not in exterior):
                        exterior.add((ny, nx))
                        flood.append((ny, nx))

            has_hole = any(
                (y, x) not in cells and (y, x) not in exterior
                for y in range(minr, maxr + 1)
                for x in range(minc, maxc + 1)
            )
            objects.append({
                "cells": cells,
                "top": minr,
                "bottom": maxr,
                "left": minc,
                "frame": has_hole,
            })

    placed = []
    for is_frame in (True, False):
        group = [obj for obj in objects if obj["frame"] == is_frame]
        if is_frame:
            group.sort(key=lambda o: o["top"])
        else:
            group.sort(key=lambda o: -o["bottom"])

        for obj in group:
            top, left = obj["top"], obj["left"]
            height = obj["bottom"] - obj["top"] + 1
            offsets = [(y - top, x - left) for y, x in obj["cells"]]

            candidates = range(0, top + 1) if is_frame else range(h - height, top - 1, -1)
            chosen = top
            for candidate in candidates:
                shifted = {(candidate + dy, left + dx) for dy, dx in offsets}
                if all(not (shifted & other) for other in placed):
                    chosen = candidate
                    placed.append(shifted)
                    break
            else:
                placed.append({(top + dy, left + dx) for dy, dx in offsets})

    out = [[0] * w for _ in range(h)]
    for obj, shifted in zip(
        sorted(objects, key=lambda o: (o["frame"] is False,
                                       o["top"] if o["frame"] else -o["bottom"])),
        placed
    ):
        color = grid[next(iter(obj["cells"]))[0]][next(iter(obj["cells"]))[1]]
        for y, x in shifted:
            out[y][x] = color
    return out
